type TLMessageService struct {
	ClazzID              uint32                  `json:"_id"`
	ClazzName2           string                  `json:"_name"`
	Out                  bool                    `json:"out"`
	Mentioned            bool                    `json:"mentioned"`
	MediaUnread          bool                    `json:"media_unread"`
	ReactionsArePossible bool                    `json:"reactions_are_possible"`
	Silent               bool                    `json:"silent"`
	Post                 bool                    `json:"post"`
	Legacy               bool                    `json:"legacy"`
	Id                   int32                   `json:"id"`
	FromId               PeerClazz               `json:"from_id"`
	PeerId               PeerClazz               `json:"peer_id"`
	SavedPeerId          PeerClazz               `json:"saved_peer_id"`
	ReplyTo              MessageReplyHeaderClazz `json:"reply_to"`
	Date                 int32                   `json:"date"`
	Action               MessageActionClazz      `json:"action"`
	Reactions            MessageReactionsClazz   `json:"reactions"`
	TtlPeriod            *int32                  `json:"ttl_period"`
}

func MakeTLMessageService(m *TLMessageService) *TLMessageService {
	if m == nil {
		return nil
	}
	m.ClazzName2 = ClazzName_messageService

	return m
}

func (m *TLMessageService) String() string {
	wrapper := iface.WithNameWrapper{"messageService", m}
	return wrapper.String()
}

// MessageClazzName <--
func (m *TLMessageService) MessageClazzName() string {
	return ClazzName_messageService
}

// ClazzName <--
func (m *TLMessageService) ClazzName() string {
	return m.ClazzName2
}

// ToMessage <--
func (m *TLMessageService) ToMessage() *Message {
	if m == nil {
		return nil
	}

	return &Message{Clazz: m}
}

// Encode <--
func (m *TLMessageService) Encode(x *bin.Encoder, layer int32) error {
	var encodeF = map[uint32]func() error{
		0x7a800e0a: func() error {
			x.PutClazzID(0x7a800e0a)

			// set flags
			var getFlags = func() uint32 {
				var flags uint32 = 0

				if m.Out == true {
					flags |= 1 << 1
				}
				if m.Mentioned == true {
					flags |= 1 << 4
				}
				if m.MediaUnread == true {
					flags |= 1 << 5
				}
				if m.ReactionsArePossible == true {
					flags |= 1 << 9
				}
				if m.Silent == true {
					flags |= 1 << 13
				}
				if m.Post == true {
					flags |= 1 << 14
				}
				if m.Legacy == true {
					flags |= 1 << 19
				}

				if m.FromId != nil {
					flags |= 1 << 8
				}

				if m.SavedPeerId != nil {
					flags |= 1 << 28
				}
				if m.ReplyTo != nil {
					flags |= 1 << 3
				}

				if m.Reactions != nil {
					flags |= 1 << 20
				}
				if m.TtlPeriod != nil {
					flags |= 1 << 25
				}

				return flags
			}

			// set flags
			var flags = getFlags()
			x.PutUint32(flags)
			x.PutInt32(m.Id)
			if m.FromId != nil {
				_ = m.FromId.Encode(x, layer)
			}

			_ = m.PeerId.Encode(x, layer)
			if m.SavedPeerId != nil {
				_ = m.SavedPeerId.Encode(x, layer)
			}

			if m.ReplyTo != nil {
				_ = m.ReplyTo.Encode(x, layer)
			}

			x.PutInt32(m.Date)
			_ = m.Action.Encode(x, layer)
			if m.Reactions != nil {
				_ = m.Reactions.Encode(x, layer)
			}

			if m.TtlPeriod != nil {
				x.PutInt32(*m.TtlPeriod)
			}

			return nil
		},
	}

	clazzId := iface.GetClazzIDByName(ClazzName_messageService, int(layer))
	if f, ok := encodeF[clazzId]; ok {
		return f()
	} else {
		// TODO(@benqi): handle error
		return fmt.Errorf("not found clazzId by (%s, %d)", ClazzName_messageService, layer)
	}
}

