// Message <--
type Message struct {
	// ClazzID   uint32 `json:"_id"`
	// ClazzName string `json:"_name"`
	Clazz MessageClazz `json:"_clazz"`
}

func (m *Message) ClazzName() string {
	if m.Clazz == nil {
		return ""
	} else {
		return m.Clazz.MessageClazzName()
	}
}

func (m *Message) String() string {
	wrapper := iface.WithNameWrapper{m.ClazzName(), m}
	return wrapper.String()
}

// Encode <--
func (m *Message) Encode(x *bin.Encoder, layer int32) error {
	if m.Clazz != nil {
		return m.Clazz.Encode(x, layer)
	}

	return fmt.Errorf("Message - invalid Clazz")
}

// Decode <--
func (m *Message) Decode(d *bin.Decoder) (err error) {
	m.Clazz, err = DecodeMessageClazz(d)
	return
}

// Match <--
func (m *Message) Match(f ...interface{}) {
	if m.Clazz == nil {
		return
	}

	switch c := m.Clazz.(type) {
	case *TLMessageEmpty:
		for _, v := range f {
			if f1, ok := v.(func(c *TLMessageEmpty) interface{}); ok {
				f1(c)
			}
		}
	case *TLMessage:
		for _, v := range f {
			if f1, ok := v.(func(c *TLMessage) interface{}); ok {
				f1(c)
			}
		}
	case *TLMessageService:
		for _, v := range f {
			if f1, ok := v.(func(c *TLMessageService) interface{}); ok {
				f1(c)
			}
		}
	default:
		//
	}
}

